import{_ as r,h as o,i as e,c as n,v as t,p,x as i,m as s,e as c,S as m}from"./chunks/framework.Dvtg8yj2.js";const P=JSON.parse('{"title":"Reject Sampling / RFT","description":"","frontmatter":{"title":"Reject Sampling / RFT","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rejection-sampling-rft.md","filePath":"llm/rejection-sampling-rft.md","lastUpdated":1788454257000}'),h={name:"llm/rejection-sampling-rft.md"};function d(R,a,T,F,f,S){const l=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="reject-sampling-rft" tabindex="-1">Reject Sampling / RFT <a class="header-anchor" href="#reject-sampling-rft" aria-label="Permalink to &quot;Reject Sampling / RFT&quot;">​</a></h1><div class="epigraph"><p>先按现行策略多写几条，再用奖励或核对器留下合格的，最后把留下的当示范做监督学习。没有策略梯度，也没有价值函数。</p><footer>—— 接到 Ouyang 等人的最优选作答；Llama 2 与 DeepSeek-R1 中的拒绝采样阶段</footer></div><p>拒绝采样微调（常写作 RFT：Rejection sampling Fine-Tuning）把强化学习缩成「采样—筛选—SFT」三步。策略（或 SFT 模型）对每个提示生成 \\(N\\) 条完成，奖励模型、规则核对器或人工留下通过的子集，学生（通常就是同一策略）在子集上做因果 LM。Ouyang 等人用最优选（best-of-\\(N\\)）作答作为与 PPO 对照的推理时基线；训练里把胜方写回数据集，就是同一思想的离线版。Llama 2 的对话对齐写明使用拒绝采样；DeepSeek-R1 在多阶段里用拒绝采样再 SFT，把 RL 轨迹里可读、可核验的样本冻成示范。它与 <a href="/llm/sequence-distill">序列蒸馏</a> 共用「完整序列当标签」，筛选器从教师换成了奖励。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PPO 要在线生成、四模型常驻、调 KL 与 critic。许多团队已经有可用的 RM 或可验证奖励，却负担不起稳定的 actor-critic。他们需要一种把「高分样本」变成参数更新的办法，且更新规则必须是普通 SFT——优化器、并行、检查点都复用指令微调栈。</p><p>拒绝采样回答的是：若我能从 \\(\\pi\\) 里抽出 RM 更高或核对通过的 \\(y\\)，最大似然这些 \\(y\\) 能否把 \\(\\pi\\) 推向高奖励区。能，但只沿着「已经采到的支撑集」推，不会主动去探索 RM 的未知漏洞以外的新句式——探索完全来自采样温度与 \\(N\\)。\\(N=1\\) 且不过滤，退化为普通 SFT；\\(N\\) 很大而 RM 有偏，退化为高效的奖励黑客模仿。</p><h3 id="与推理时-best-of-n-不是同一层" tabindex="-1">与推理时 Best-of-N 不是同一层 <a class="header-anchor" href="#与推理时-best-of-n-不是同一层" aria-label="Permalink to &quot;与推理时 Best-of-N 不是同一层&quot;">​</a></h3><p>推理时 Best-of-N：部署仍用旧权重，每次请求采 \\(N\\) 条再拣一条，算力花在服务延迟上。RFT：拣选发生在训练期，部署仍是一条 decode。Ouyang 把 Best-of-N 当作评估 RLHF 收益的参照；那是测试时计算。RFT 把参照写进权重，测试时可以 \\(N=1\\)。不要把论文里的 Best-of-N 曲线直接写成「我们做了 RFT」。</p><p><span class="marginnote">筛选器可以是 RM、编译器、数学等式、或「格式标签是否齐全」。可验证域应优先规则，少用 RM，以免把讨好句式写进示范。R1 的拒绝采样阶段服务的是可读性与正确轨迹的冻结，不是再训一个 critic。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对提示集 \\(\\mathcal{D}\\)，现行策略 \\(\\pi\\) 采 \\(\\{y_i\\}_{i=1}^N\\)，得分 \\(s(x,y_i)\\)。接受规则可以是：取 argmax、取高于阈值、取通过核对的全部、或按分加权。接受集上</p> \\[\\mathcal{L}_{\\mathrm{RFT}} = -\\mathbb{E}_{(x,y)\\sim \\mathrm{Accept}(\\pi,s)}[\\log\\pi_\\theta(y\\mid x)] \\]<p>\\(\\pi_\\theta\\) 可从 \\(\\pi\\) 初始化。一轮之后 \\(\\pi\\) 变了，应再采样再筛，否则数据相对新策略离线过期——与 <a href="/llm/online-offline-distill">离线蒸馏</a> 同一时间表。多轮 RFT 是「离线 RL」的极简版：没有重要性加权，把过期完全交给周期性刷新。</p><p>\\(N\\) 与温度决定候选覆盖。温度过低，N 条近重复，筛选没有信息；过高，通过率塌掉，接受集太小，过拟合几条幸运轨迹。应按接受率而不是按 \\(N\\) 的名义值去调。同一 \\(x\\) 若零通过，应丢弃或改提示，不要把失败样本当负 SFT——那是另一种目标，需要显式的负对数或对比损失，不是拒绝采样的定义。</p>',14)),(e(),p(m,null,{default:i(()=>[c(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%8F%90%E7%A4%BA%20x%22%5D%20--%3E%20SAM%5B%22%CF%80%20%E9%87%87%E6%A0%B7%20N%20%E6%9D%A1%22%5D%0A%20%20SAM%20--%3E%20SC%5B%22RM%20%2F%20%E6%A0%B8%E5%AF%B9%E5%99%A8%E6%89%93%E5%88%86%22%5D%0A%20%20SC%20--%3E%20ACC%5B%22%E6%8E%A5%E5%8F%97%E5%AD%90%E9%9B%86%22%5D%0A%20%20ACC%20--%3E%20SFT%5B%22%E5%9B%A0%E6%9E%9C%20LM%22%5D%0A%20%20SFT%20--%3E%20PI%5B%22%E6%9B%B4%E6%96%B0%20%CF%80%22%5D%0A%20%20PI%20--%3E%20SAM%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="和-ppo-的梯度差在哪" tabindex="-1">和 PPO 的梯度差在哪 <a class="header-anchor" href="#和-ppo-的梯度差在哪" aria-label="Permalink to &quot;和 PPO 的梯度差在哪&quot;">​</a></h3><p>PPO 对未接受的样本也给梯度：负优势降低其概率。RFT 对未接受样本的梯度为零——它们根本不进 batch。于是「明显更差」的完成不会被主动压低，只是相对地越来越少被采样到。若差样本与好样本共享大量前缀，只学好样本也可能抬高差样本的前缀概率。这是最大似然筛选数据的固有缝，要用多样化的负例协议或真正的偏好对才能补，那已经离开 RFT。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>在奖励把序列排成全序、且 \\(\\pi\\) 对高分区仍有覆盖时，反复「采—筛—SFT」近似一种硬 EM：E 步用现行策略提出候选，M 步把质量高的当成标签。没有价值函数，基线是「没被选中就不出现」。方差表现为：小接受集上的过拟合、以及筛选器噪声被当成确定性标签。</p><p>与教师序列蒸馏的差别是标签来源。蒸馏的 \\(y\\) 来自更强教师，筛选可选；RFT 的 \\(y\\) 来自自己（或同族策略），筛选是必须的，否则就是在自己的随机噪声上 SFT，会强化平均水平而不是上尾。实践中两者常拼接：教师或 RL 策略写出长链，核对通过后当 RFT / 蒸馏语料，学生只做 SFT。DeepSeek-R1 蒸馏段不再 RL，本质是高质量拒绝样本上的序列模仿。</p><p><span class="marginnote">接受规则一变，整份数据的定义就变。必须把 \\(N\\)、温度、阈值、核对脚本的版本写进数据集名。只记「RFT 一轮」无法复现。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><h3 id="它不能替代探索性-rl" tabindex="-1">它不能替代探索性 RL <a class="header-anchor" href="#它不能替代探索性-rl" aria-label="Permalink to &quot;它不能替代探索性 RL&quot;">​</a></h3><p>RFT 不会为了抬奖励去发明 SFT 没写过的推理模式——除非采样偶然打出，并被筛选器留下。R1-Zero 那种「长链自己长出来」依赖策略梯度对可验证奖励的探索，不是拒绝采样能替代的。已有较强 SFT、只需把上尾质量写进权重、并想避开 critic 时，RFT 很合适。从基座空转探索时，应走 GRPO / PPO 一类在线 RL。</p><p>RM 当筛选器时，黑客会被高效写入示范，比 PPO 还干净：因为 SFT 会把黑客句式当标准答案记住，KL 锚也没有第三阶段那种逐步惩罚（除非你在 SFT 里另加）。可验证奖励上 RFT 干净得多，仍要防「答案对、过程胡编」的假推理，与 <a href="/llm/cot-distill">链蒸馏</a> 同一风险。</p><p><span class="marginnote">Llama 2 同时使用拒绝采样与 PPO，说明二者可作流水线相邻阶段，而不是论文竞赛里的互斥宗教。顺序通常是：SFT →（可选 RFT）→ 在线 RL →（可选再 RFT 冻可读样本）。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RFT 用现行策略多样本，经 RM 或核对器接受后做 SFT，无 critic、无策略梯度。</li><li>未接受样本不产生负梯度；探索只来自采样与轮次刷新。</li><li>推理时 Best-of-N 花的是延迟；RFT 把拣选写进权重。</li><li>适合榨上尾、避开 PPO 稳定性；不适合从零涌现长链推理。</li><li>出处：Ouyang et al., NeurIPS 2022（Best-of-N 对照与偏好数据）；拒绝采样出现在 Llama 2 与 DeepSeek-R1 的后训练描述中。</li></ul>',13))])}const u=r(h,[["render",d]]);export{P as __pageData,u as default};
